pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _depositAmt, uint256 _collectAmt, uint256 _warpTimestamp) public {
        // Bound admissible domain: collect amount must be >= MinSum (1 ether), and at most deposited amount
        vm.assume(_depositAmt >= 1 ether);
        vm.assume(_collectAmt >= 1 ether && _collectAmt <= _depositAmt);
        vm.assume(_unlockTime > block.timestamp);
        // Warp to a time before unlockTime, to guarantee condition fails in reference
        vm.assume(_warpTimestamp <= _unlockTime);
        vm.warp(_warpTimestamp);

        address actor = address(0x1111);
        vm.deal(actor, _depositAmt);

        // Deposit ETH, setting unlockTime
        vm.prank(actor);
        c.Put{value: _depositAmt}(_unlockTime);

        // Warp again to same timestamp to ensure clean state before Collect
        vm.warp(_warpTimestamp);

        uint256 balanceBefore = address(c).balance;
        bool ok = false;

        vm.prank(actor);
        try c.Collect(_collectAmt) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;

        // The rule: if Collect did not revert, the contract balance must have decreased;
        // otherwise, if it reverted, the contract balance must stay unchanged.
        // The reference respects this: before unlockTime, it always reverts because missing unlockTime condition,
        // so balanceAfter == balanceBefore, and `ok` is false => assertTrue(!ok && balanceAfter == balanceBefore).
        // The mutant: before unlockTime, `ok` becomes true and balanceAfter < balanceBefore, breaking the property.
        // We encode the property: ok => (balanceAfter < balanceBefore) AND !ok => (balanceAfter == balanceBefore)
        bool propertyHolds = (ok ? (balanceAfter < balanceBefore) : (balanceAfter == balanceBefore));
        assertTrue(propertyHolds);
    }
}

