pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 depositAmount) public {
        // Restrict to admissible domain: amount > 0, unlockTime > now, depositAmount >= amount + 1 ether
        vm.assume(amount > 0);
        vm.assume(unlockTime > block.timestamp);
        vm.assume(depositAmount >= amount + 1 ether);

        address actor = address(0x1234);
        vm.deal(actor, depositAmount);

        // Actor deposits and sets a future unlockTime
        vm.prank(actor);
        c.Put{value: depositAmount}(unlockTime);

        // Ensure block.timestamp is still before unlockTime
        vm.warp(block.timestamp + 1);
        vm.assume(block.timestamp < unlockTime);

        // Record balance and whether Collect succeeds
        uint256 balanceBefore = actor.balance;
        bool success;
        vm.prank(actor);
        try c.Collect(amount) { success = true; } catch { success = false; }
        uint256 balanceAfter = actor.balance;

        // In reference, Collect before unlockTime MUST fail (success == false) and balance unchanged.
        // In mutant, Collect may succeed and steal funds, changing balance.
        // Assert: if block.timestamp < unlockTime, Collect never succeeds AND actor balance unchanged.
        assertTrue(!success && balanceAfter == balanceBefore);
    }
}

