contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockDelay) public {
        // admissible: amount >= 1 ether (to pass MinSum), delay in 1..365 days to stay in future
        vm.assume(amount >= 1 ether && amount <= 100 ether);
        vm.assume(unlockDelay >= 1 days && unlockDelay <= 365 days);
        address caller = address(0x1234);
        vm.deal(caller, amount);
        uint256 nowTs = block.timestamp;
        uint256 unlockTime = nowTs + unlockDelay;

        // call Put to set balance and future unlockTime
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);

        // record balance before Collect attempt
        uint256 balBefore = c.Acc(caller).balance;
        // call Collect before unlockTime; block.timestamp < unlockTime
        bool ok;
        vm.prank(caller);
        try c.Collect(amount) { ok = true; } catch { ok = false; }
        uint256 balAfter = c.Acc(caller).balance;

        // invariant: if collect happens before unlockTime, balance must not decrease
        // reference reverts (ok=false) so balAfter==balBefore; mutant may succeed (ok=true) and decrease balance
        if (block.timestamp < unlockTime) {
            assertTrue(balAfter == balBefore);
        }
    }
}

